statements:
-- 1) A view passa a respeitar as permissões/RLS do usuário chamador.
ALTER VIEW public.psb_product_shipping_pending SET (security_invoker = true);

-- A view é somente leitura para clientes e usuários autenticados.
REVOKE ALL PRIVILEGES ON TABLE public.psb_product_shipping_pending FROM anon, authenticated;
GRANT SELECT ON TABLE public.psb_product_shipping_pending TO anon, authenticated;

-- 2) Funções auxiliares de RLS não precisam de SECURITY DEFINER.
-- Como psb_user_roles já possui RLS permitindo ao usuário ler apenas o próprio papel,
-- SECURITY INVOKER preserva o funcionamento e elimina execução privilegiada desnecessária.
CREATE OR REPLACE FUNCTION public.psb_is_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = pg_catalog
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.psb_user_roles
    WHERE user_id = auth.uid()
      AND role = 'admin'
  );
$function$;

CREATE OR REPLACE FUNCTION public.psb_current_seller_id()
RETURNS text
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = pg_catalog
AS $function$
  SELECT seller_id
  FROM public.psb_user_roles
  WHERE user_id = auth.uid();
$function$;

ALTER FUNCTION public.psb_set_updated_at() SET search_path = pg_catalog;

-- Evita RPC anônimo das funções auxiliares.
REVOKE ALL ON FUNCTION public.psb_is_admin() FROM PUBLIC, anon;
