CREATE OR REPLACE FUNCTION public.psb_strip_legacy_seller_secrets()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO pg_catalog
AS $$
BEGIN
  NEW.password := NULL;
  NEW.seller_payload := COALESCE(NEW.seller_payload, '{}'::jsonb)
    - 'password' - 'senha' - 'pin' - 'adminPin' - 'access_pin';
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_psb_strip_legacy_seller_secrets ON public.psb_sellers;
