BEFORE INSERT OR UPDATE ON public.psb_sellers
FOR EACH ROW
EXECUTE FUNCTION public.psb_strip_legacy_seller_secrets();

-- Sanitize any legacy values that may still exist.
UPDATE public.psb_sellers
SET password = NULL,
    seller_payload = COALESCE(seller_payload, '{}'::jsonb)
      - 'password' - 'senha' - 'pin' - 'adminPin' - 'access_pin'
WHERE password IS NOT NULL
   OR COALESCE(seller_payload, '{}'::jsonb) ?| ARRAY['password','senha','pin','adminPin','access_pin'];

