CREATE OR REPLACE FUNCTION public.psb_write_security_audit()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO pg_catalog
AS $$
DECLARE
  v_key text;
  v_details jsonb := '{}'::jsonb;
BEGIN
  IF TG_TABLE_NAME = 'psb_sellers' THEN
    v_key := COALESCE(NEW.seller_id, OLD.seller_id);
    v_details := jsonb_build_object(
      'seller_id', v_key,
      'status_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.status ELSE NULL END,
      'status_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.status ELSE NULL END,
      'login_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.login ELSE NULL END,
      'login_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.login ELSE NULL END
    );
  ELSIF TG_TABLE_NAME = 'psb_seller_offers' THEN
    v_key := COALESCE(NEW.offer_key, OLD.offer_key);
    v_details := jsonb_build_object(
      'offer_key', v_key,
      'seller_id', COALESCE(NEW.seller_id, OLD.seller_id),
      'scope', COALESCE(NEW.scope, OLD.scope),
      'product_slug', COALESCE(NEW.product_slug, OLD.product_slug),
      'category_slug', COALESCE(NEW.category_slug, OLD.category_slug),
      'active_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.active ELSE NULL END,
      'active_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.active ELSE NULL END
    );
  ELSIF TG_TABLE_NAME = 'psb_seller_shipping_settings' THEN
    v_key := COALESCE(NEW.seller_id, OLD.seller_id);
    v_details := jsonb_build_object(
      'seller_id', v_key,
      'origin_city', COALESCE(NEW.origin_city, OLD.origin_city),
      'origin_uf', COALESCE(NEW.origin_uf, OLD.origin_uf),
      'allow_external_shipping_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.allow_external_shipping ELSE NULL END,
      'allow_external_shipping_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.allow_external_shipping ELSE NULL END,
      'active_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.active ELSE NULL END,
      'active_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.active ELSE NULL END
    );
  ELSIF TG_TABLE_NAME = 'psb_seller_shipping_rules' THEN
    v_key := COALESCE(NEW.rule_key, OLD.rule_key);
    v_details := jsonb_build_object(
      'rule_key', v_key,
      'seller_id', COALESCE(NEW.seller_id, OLD.seller_id),
      'scope', COALESCE(NEW.scope, OLD.scope),
      'product_slug', COALESCE(NEW.product_slug, OLD.product_slug),
      'category_slug', COALESCE(NEW.category_slug, OLD.category_slug),
      'active_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.active ELSE NULL END,
      'active_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.active ELSE NULL END
    );
  ELSIF TG_TABLE_NAME = 'psb_user_roles' THEN
    v_key := COALESCE(NEW.user_id, OLD.user_id)::text;
    v_details := jsonb_build_object(
      'user_id', v_key,
      'role_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.role ELSE NULL END,
      'role_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.role ELSE NULL END,
      'seller_id_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.seller_id ELSE NULL END,
      'seller_id_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.seller_id ELSE NULL END
    );
  ELSIF TG_TABLE_NAME = 'psb_orders' THEN
    v_key := COALESCE(NEW.order_number, OLD.order_number);
    v_details := jsonb_build_object(
      'order_number', v_key,
      'seller_id', COALESCE(NEW.seller_id, OLD.seller_id),
      'status_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.status ELSE NULL END,
      'status_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.status ELSE NULL END,
      'payment_released_before', CASE WHEN TG_OP <> 'INSERT' THEN OLD.payment_released ELSE NULL END,
      'payment_released_after', CASE WHEN TG_OP <> 'DELETE' THEN NEW.payment_released ELSE NULL END
    );
  ELSE
    v_key := NULL;
    v_details := jsonb_build_object('table', TG_TABLE_NAME);
  END IF;

  INSERT INTO public.psb_security_audit_log(table_name, action, record_key, actor_uid, actor_role, details)
  VALUES (TG_TABLE_NAME, TG_OP, v_key, auth.uid(), auth.role(), v_details);

  RETURN COALESCE(NEW, OLD);
END;
$$;

