create or replace function public.psb_html_escape_text(p_value text)
returns text
language sql
immutable
strict
set search_path = 'pg_catalog'
as $function$
  select replace(
           replace(
             replace(
               replace(
                 replace(p_value, '&', '&amp;'),
               '<', '&lt;'),
             '>', '&gt;'),
           '"', '&quot;'),
         '''', '&#39;');
$function$;

create or replace function public.psb_html_escape_jsonb(p_value jsonb)
returns jsonb
language plpgsql
immutable
strict
set search_path = 'pg_catalog'
as $function$
declare
  v_type text;
  v_result jsonb;
begin
  v_type := jsonb_typeof(p_value);

  if v_type = 'string' then
    return to_jsonb(public.psb_html_escape_text(p_value #>> '{}'));
  elsif v_type = 'array' then
    select coalesce(jsonb_agg(public.psb_html_escape_jsonb(value)), '[]'::jsonb)
      into v_result
      from jsonb_array_elements(p_value);
    return v_result;
  elsif v_type = 'object' then
    select coalesce(jsonb_object_agg(key, public.psb_html_escape_jsonb(value)), '{}'::jsonb)
      into v_result
      from jsonb_each(p_value);
    return v_result;
  else
    return p_value;
  end if;
end;
$function$;

create or replace function public.psb_order_items_valid(p_items jsonb, p_seller_id text)
returns boolean
language plpgsql
immutable
strict
set search_path = 'pg_catalog'
as $function$
declare
  v_item jsonb;
  v_qty numeric;
  v_preco numeric;
  v_slug text;
  v_item_seller text;
begin
  if jsonb_typeof(p_items) <> 'array' then
    return false;
  end if;

  if jsonb_array_length(p_items) < 1 or jsonb_array_length(p_items) > 200 then
    return false;
  end if;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    if jsonb_typeof(v_item) <> 'object' then
      return false;
    end if;

    if not (v_item ? 'nome' and v_item ? 'qty' and v_item ? 'preco') then
      return false;
    end if;

    if length(btrim(coalesce(v_item ->> 'nome',''))) < 1
       or length(v_item ->> 'nome') > 200
       or length(coalesce(v_item ->> 'variacao','')) > 240
       or length(coalesce(v_item ->> 'sellerName','')) > 160
       or length(coalesce(v_item ->> 'sellerLabel','')) > 200
       or length(coalesce(v_item ->> 'key','')) > 300
       or length(coalesce(v_item ->> 'img','')) > 500 then
      return false;
    end if;

    v_slug := coalesce(v_item ->> 'slug','');
    if v_slug <> '' and (length(v_slug) > 120 or v_slug !~ '^[a-z0-9][a-z0-9-]*$') then
      return false;
    end if;

    v_item_seller := coalesce(v_item ->> 'sellerId','');
    if v_item_seller <> '' and v_item_seller <> p_seller_id then
      return false;
    end if;

    begin
      v_qty := (v_item ->> 'qty')::numeric;
      v_preco := (v_item ->> 'preco')::numeric;
    exception when others then
      return false;
    end;

    if v_qty < 1 or v_qty > 10000 or trunc(v_qty) <> v_qty then
      return false;
    end if;

    if v_preco < 0 or v_preco > 1000000 then
      return false;
    end if;
  end loop;

  return true;
end;
$function$;

