create or replace function public.psb_guard_seller_order_update()
returns trigger
language plpgsql
set search_path = 'pg_catalog'
as $function$
declare
  v_is_admin boolean := false;
  v_seller_id text;
  v_payment_released boolean;
begin
  v_is_admin := public.psb_is_admin();
  if v_is_admin then
    return new;
  end if;

  if auth.role() <> 'authenticated' then
    raise exception 'order update requires authenticated user';
  end if;

  v_seller_id := public.psb_current_seller_id();
  if v_seller_id is null or old.seller_id is distinct from v_seller_id then
    raise exception 'seller cannot update this order';
  end if;

  if new.order_number is distinct from old.order_number
     or new.seller_id is distinct from old.seller_id
     or new.seller_name is distinct from old.seller_name
     or new.customer is distinct from old.customer
     or new.items is distinct from old.items
     or new.subtotal is distinct from old.subtotal
     or new.source is distinct from old.source
     or new.created_at is distinct from old.created_at then
    raise exception 'seller may update only order workflow status';
  end if;

  v_payment_released := new.status in ('aprovado-para-pagamento','pago','em-separacao','enviado','concluido');
  new.payment_released := v_payment_released;
  new.updated_at := now();

  if new.status is distinct from old.status then
    new.timeline := coalesce(old.timeline, '[]'::jsonb) || jsonb_build_array(
      jsonb_build_object(
        'status', new.status,
        'at', new.updated_at,
        'note', 'Status atualizado pela loja.'
      )
    );
  else
    new.timeline := old.timeline;
  end if;

  new.order_payload := coalesce(old.order_payload, '{}'::jsonb)
    || jsonb_build_object(
      'status', new.status,
      'paymentReleased', new.payment_released,
      'updatedAt', new.updated_at,
      'timeline', new.timeline
    );

  return new;
end;
$function$;

